import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        int start = nextInt(), n = s.length(), difference = 0;
        for (int i = 0; i < n; i++) difference += s.charAt(i) == 'a' ? 1 : -1;
        if (difference == 0) {
            System.out.println(0);
            return;
        }
        int answer = Integer.MAX_VALUE;
        // walk straight left or right; each crossed edge flips its letter
        for (int direction : new int[] {-1, 1}) {
            int delta = difference, p = start, steps = 0;
            while (p + direction >= 0 && p + direction <= n) {
                int edge = direction == 1 ? p : p - 1;
                delta += s.charAt(edge) == 'a' ? -2 : 2;
                p += direction;
                steps++;
                if (delta == 0) answer = Math.min(answer, steps);
            }
        }
        System.out.println(answer == Integer.MAX_VALUE ? -1 : answer);
    }
}

package main

import (
	"fmt"
	"math"
)

func main() {
	var s string
	var start int
	fmt.Scan(&s, &start)
	n, difference := len(s), 0
	for _, c := range s {
		if c == 'a' {
			difference++
		} else {
			difference--
		}
	}
	if difference == 0 {
		fmt.Println(0)
		return
	}
	answer := math.MaxInt
	// walk straight left or right; each crossed edge flips its letter
	for _, direction := range []int{-1, 1} {
		delta, p, steps := difference, start, 0
		for p+direction >= 0 && p+direction <= n {
			edge := p
			if direction == -1 {
				edge = p - 1
			}
			if s[edge] == 'a' {
				delta -= 2
			} else {
				delta += 2
			}
			p += direction
			steps++
			if delta == 0 {
				answer = min(answer, steps)
			}
		}
	}
	if answer == math.MaxInt {
		answer = -1
	}
	fmt.Println(answer)
}
